-- Retire the legacy /api/team invite flow.
--
-- Before: `workspace_invites` stored tokens generated by the now-removed
-- POST /api/team/invites endpoint. Accepting one of those tokens hit
-- POST /api/team/invites/accept and inserted a row into `workspace_members`,
-- but it never created a session — so invitees still had to sign in through
-- the real auth flow afterwards.
--
-- The real invite flow lives in `invitations` (see shared/models/auth.ts +
-- server/auth/local-routes.ts) and is the only path the UI calls now. This
-- migration drops the orphaned table so it can't accidentally be written to
-- again, and so a future `drizzle-kit push` doesn't try to recreate it from
-- a stale schema snapshot.
--
-- `workspace_members` is intentionally kept: it remains the read-only mirror
-- of `memberships` that backs `req.member` in the rbac middleware. See the
-- comment on `workspaceMembers` in shared/schema.ts.

DROP TABLE IF EXISTS workspace_invites;
